import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean).sort((a,b)=>a.localeCompare(b));
export function verifyWordCoverageRelease(read=readFileSync){
 const r=JSON.parse(read('docs/klink-owner-release-word-coverage-20261031.json'));
 assert.equal(r.approvedBy,'Nico');assert.equal(r.publicationApproved,true);assert.equal(r.userRequest,'Ja, begin met die twintig ontbrekende combinaties bij Woorden oefenen. Volg je advies, behoud het vastgezette uiterlijk en de voortgang, controleer alles en zet het live. Geef mij weer een directe link naar het resultaat.');assert.equal(r.baselineSourceCommit,'d6246bf96c0aea01e230d5ef576fe0365f368b9c');assert.equal(r.liveSourceCommit,'d6246bf96c0aea01e230d5ef576fe0365f368b9c');git('merge-base','--is-ancestor',r.liveSourceCommit,r.baselineSourceCommit);git('merge-base','--is-ancestor',r.baselineSourceCommit,'HEAD');
 const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
 const changed=[...new Set([...lines(git('diff','--name-only',r.baselineSourceCommit,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])].sort((a,b)=>a.localeCompare(b));assert.deepEqual(changed,[...r.changedFiles].sort((a,b)=>a.localeCompare(b)));
 const allowed=['scripts/check-image-size-release-20261031.mjs','scripts/check-docent-lessons-release-20261031.mjs','lib/imported-practice.ts','components/product/imported-practice-surface.tsx','data/klink-production-index.json','data/klink-word-round-index.json','data/klink-word-use-self.json','scripts/check-word-library-release-20261031.mjs','data/klink-word-library-index.json','scripts/test-production-answers.mjs','components/product/package-exercise-browser.tsx','scripts/check-word-coverage-release-20261031.mjs','scripts/test-word-coverage-release-20261031.mjs','scripts/test-word-coverage-20261031.mjs','scripts/test-practice-chapters.mjs','scripts/test-production-content.mjs','public/klink-woorden-aanvulling-20261031.html'];assert(changed.every(f=>allowed.includes(f)||/^public\/practice-content\/word-self-20261031\/[a-z0-9-]+\.json$/.test(f)),'Only approved practice coverage scope');for(const f of changed)assert.equal(sha(read(f)),r.files[f],f);
 assert.deepEqual(lines(git('diff','--name-only','--diff-filter=MD',r.baselineSourceCommit,'--','public')),[],'All previously published media and assets preserved');
 const component='components/product/imported-practice-surface.tsx',before=git('show',r.baselineSourceCommit+':'+component).toString();assert.equal(read(component).toString(),before.replace('const [prepared, setPrepared] = useState(false);',"const [prepared, setPrepared] = useState(exercise.access === 'self-practice');"));
 const attempt='components/product/package-exercise-browser.tsx';assert.equal(read(attempt).toString(),git('show',r.baselineSourceCommit+':'+attempt).toString().replace("independentReading: false, reviewEligible: false, access: 'teacher-supported'","independentReading: false, reviewEligible: false, access: exercise.access === 'self-practice' ? 'self-practice' : 'teacher-supported'"));
 const floor=JSON.parse(read('docs/appearance-floor-20261031/floor.json'));for(const f of Object.keys(floor.referenceFiles))assert.equal(sha(read(f)),sha(git('show',r.baselineSourceCommit+':'+f)),'Approved current appearance: '+f);
 const q=JSON.parse(read('docs/word-coverage-release-20261031/verification.json'));for(const k of['twentyCombinations','answers','levels','progress','audioMetadata','appearance','teacherPreserved','types','lint','build','browser','localOnly'])assert.equal(q[k],true,k);assert.equal(q.humanListening,'not repeated; existing audio retained');
 for(const[f,h]of Object.entries(r.evidence))assert.equal(sha(read(f)),h,f);
 const audio=JSON.parse(read('docs/word-coverage-release-20261031/audio-check.json'));assert(audio.length>1000);for(const a of audio){assert(a.metadataValid&&a.decodes);assert.equal(a.tags.artist,'Taalroute');assert.equal(a.tags.publisher,'Taalroute');assert.equal(sha(read('public'+a.src)),a.sha256,a.src);}
 const backup=JSON.parse(read('docs/word-coverage-release-20261031/backup.json'));assert(backup.verified&&backup.driveId&&backup.sha256);for(const f of changed)assert.equal(backup.files[f],r.files[f],f);return r;
}
export function readBeforeWordCoverage(file,r,read=readFileSync){return r.changedFiles.includes(file)?git('show',r.baselineSourceCommit+':'+file):read(file);}
